=== FILE: rr_arbiter.v ===
// rr_arbiter.v -- round-robin arbiter for N requesters (default 4).
// Implements microarchitecture.md for the interface in interface_spec.md
// (rr_arbiter fixture). Requirement: a round-robin arbiter for four requesters.
//
// State: one priority pointer `ptr` ($clog2(N) bits), reset to 0.
// Grant: combinational search from `ptr` upwards, wrapping explicitly from
//        N-1 to 0, so N need not be a power of two.
// Update: on a rising edge with a grant, ptr <= winner + 1 (wrapping);
//         with no request ptr holds; on reset (synchronous, active low) ptr <= 0.
module rr_arbiter #(
    parameter integer N = 4
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire [N-1:0] req,
    output reg  [N-1:0] grant
);

    localparam integer  PW     = (N > 1) ? $clog2(N) : 1;
    localparam integer  LAST_I = N - 1;
    localparam integer  ONE_I  = 1;
    localparam [PW-1:0] LAST   = LAST_I[PW-1:0];
    localparam [PW-1:0] ONE_P  = ONE_I[PW-1:0];

    reg [PW-1:0] ptr;
    reg [PW-1:0] ptr_next;
    reg [PW-1:0] winner;
    reg [PW-1:0] idx;
    reg          found;
    integer      k;

    // Wrapping priority search: first requester with req high at or after ptr.
    always @* begin
        grant  = {N{1'b0}};
        winner = {PW{1'b0}};
        found  = 1'b0;
        idx    = ptr;
        for (k = 0; k < N; k = k + 1) begin
            if (!found && req[idx]) begin
                found      = 1'b1;
                winner     = idx;
                grant[idx] = 1'b1;
            end
            idx = (idx == LAST) ? {PW{1'b0}} : idx + ONE_P;
        end
    end

    // Next pointer: one past the winner, wrapping at N; hold with no grant.
    always @* begin
        ptr_next = ptr;
        if (found) begin
            ptr_next = (winner == LAST) ? {PW{1'b0}} : winner + ONE_P;
        end
    end

    // Pointer register: synchronous active-low reset to 0.
    always @(posedge clk) begin
        if (!rst_n) begin
            ptr <= {PW{1'b0}};
        end else begin
            ptr <= ptr_next;
        end
    end

`ifdef FORMAL
    // ---------------- Design-intent properties ----------------
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    // Reset is active on the first cycle.
    always @(*) begin
        if (!f_past_valid) assume(!rst_n);
    end

    // Pointer range and grant shape.
    always @(*) begin
        if (f_past_valid) begin
            assert(ptr <= LAST);
            assert((grant & (grant - 1'b1)) == {N{1'b0}});
            assert((grant & ~req) == {N{1'b0}});
            assert((req == {N{1'b0}}) == (grant == {N{1'b0}}));
            cover(rst_n && (req == {N{1'b1}}));
            cover(rst_n && (req == {N{1'b0}}));
            cover(!rst_n && (req != {N{1'b0}}) && (ptr != {PW{1'b0}}));
        end
    end

    // Pointer update: 0 after reset, hold with no grant.
    always @(posedge clk) begin
        if (f_past_valid) begin
            if (!$past(rst_n)) begin
                assert(ptr == {PW{1'b0}});
            end else if ($past(grant) == {N{1'b0}}) begin
                assert(ptr == $past(ptr));
            end
            cover($past(rst_n) && ($past(ptr) == LAST) && (ptr == {PW{1'b0}}));
        end
    end

    genvar gi, gj;
    generate
        for (gi = 0; gi < N; gi = gi + 1) begin : g_fv
            localparam [PW-1:0] F_NEXT = (gi == N - 1) ? 0 : gi + 1;
            // Distance from the pointer to requester gi in search order.
            wire [31:0] f_di = (gi >= ptr) ? (gi - ptr) : (gi + N - ptr);
            // Cycles requester gi has waited with req held and not granted.
            reg  [PW:0] f_wait;

            always @(posedge clk) begin
                if (!rst_n || !req[gi] || grant[gi]) begin
                    f_wait <= {(PW+1){1'b0}};
                end else begin
                    f_wait <= f_wait + 1'b1;
                end
            end

            always @(*) begin
                if (f_past_valid) begin
                    // Induction invariant; implies the N-1 wait bound.
                    assert(f_wait + f_di <= N - 1);
                    if (req[gi] && (f_wait == N - 1)) assert(grant[gi]);
                    cover(rst_n && grant[gi]);
                    cover(rst_n && (f_wait == N - 1));
                end
            end

            // After a grant, the pointer is one past the winner.
            always @(posedge clk) begin
                if (f_past_valid && $past(rst_n) && $past(grant[gi])) begin
                    assert(ptr == F_NEXT);
                end
            end

            // Round-robin order: nobody between the pointer and the winner asks.
            for (gj = 0; gj < N; gj = gj + 1) begin : g_ord
                if (gj != gi) begin : g_pair
                    wire [31:0] f_dj = (gj >= ptr) ? (gj - ptr) : (gj + N - ptr);
                    always @(*) begin
                        if (f_past_valid && grant[gi] && (f_dj < f_di)) begin
                            assert(!req[gj]);
                        end
                    end
                end
            end
        end
    endgenerate
`endif

endmodule

`ifdef FORMAL
// Formal-only wrapper: proves the same properties at N=4 (power of two)
// and N=5 (not a power of two) in one job.
module rr_arbiter_formal_top (
    input wire       clk,
    input wire       rst_n,
    input wire [3:0] req4,
    input wire [4:0] req5
);
    wire [3:0] grant4;
    wire [4:0] grant5;

    rr_arbiter #(.N(4)) u_n4 (.clk(clk), .rst_n(rst_n), .req(req4), .grant(grant4));
    rr_arbiter #(.N(5)) u_n5 (.clk(clk), .rst_n(rst_n), .req(req5), .grant(grant5));
endmodule
`endif
=== END FILE ===
=== FILE: rr_arbiter_tb.v ===
// rr_arbiter_tb.v -- self-checking testbench for rr_arbiter.
// Runs N=4 and N=5 side by side, each against a reference pointer model
// checked on every rising edge, with per-requester wait counters and
// coverage counters that fail the run if a case was not reached.
module rr_arbiter_tb;

    reg            clk   = 1'b0;
    reg            rst_n = 1'b0;
    reg  [4:0]     stim  = 5'b00000;
    reg  [31:0]    lfsr  = 32'h1ACEB00C;
    reg  [8*64-1:0] nonce;
    integer        passed;
    integer        failed;
    integer        i;

    wire [3:0] req4 = stim[3:0];
    wire [4:0] req5 = stim;

    wire [31:0] p4, f4, ci4, call4, ch4, cm4, cr4;
    wire [3:0]  ca4;
    wire [31:0] p5, f5, ci5, call5, ch5, cm5, cr5;
    wire [4:0]  ca5;

    always #5 clk = ~clk;

    rr_arbiter_tb_lane #(.N(4)) lane4 (
        .clk(clk), .rst_n(rst_n), .req(req4),
        .passed(p4), .failed(f4),
        .cov_idle(ci4), .cov_alone(ca4), .cov_all(call4),
        .cov_held(ch4), .cov_maxwait(cm4), .cov_rst_traffic(cr4)
    );

    rr_arbiter_tb_lane #(.N(5)) lane5 (
        .clk(clk), .rst_n(rst_n), .req(req5),
        .passed(p5), .failed(f5),
        .cov_idle(ci5), .cov_alone(ca5), .cov_all(call5),
        .cov_held(ch5), .cov_maxwait(cm5), .cov_rst_traffic(cr5)
    );

    // One cycle of stimulus, applied at the falling edge.
    task cyc;
        input       rn;
        input [4:0] r;
        begin
            @(negedge clk);
            rst_n = rn;
            stim  = r;
        end
    endtask

    // Deterministic xorshift, identical in every simulator.
    task rnd;
        begin
            lfsr = lfsr ^ (lfsr << 13);
            lfsr = lfsr ^ (lfsr >> 17);
            lfsr = lfsr ^ (lfsr << 5);
        end
    endtask

    // Coverage goal check. Goal ids:
    // 1 no requests, 2 each requester alone, 3 everyone requesting,
    // 4 held request among changing others, 5 longest fair wait (N-1),
    // 6 reset during traffic with the pointer away from 0.
    task check;
        input   ok;
        input integer id;
        input integer n;
        begin
            if (ok) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("coverage goal %0d not reached at N=%0d", id, n);
            end
        end
    endtask

    initial begin
        passed = 0;
        failed = 0;
        nonce  = {(8*64){1'b0}};
        if ($value$plusargs("nirmaan_nonce=%s", nonce) == 0) begin
            nonce = {(8*64){1'b0}};
        end

        // Reset held (first edge is in reset), then idle.
        repeat (3) cyc(1'b0, 5'b00000);
        repeat (3) cyc(1'b1, 5'b00000);

        // Each requester alone.
        for (i = 0; i < 5; i = i + 1) begin
            repeat (2) cyc(1'b1, 5'b00001 << i);
        end

        // Everyone requesting for several rounds: strict rotation, max wait.
        repeat (15) cyc(1'b1, 5'b11111);

        // A held request among changing others.
        for (i = 0; i < 5; i = i + 1) begin
            repeat (12) begin
                rnd;
                cyc(1'b1, lfsr[4:0] | (5'b00001 << i));
            end
        end

        // Random subsets: requests dropped and raised again.
        repeat (200) begin
            rnd;
            cyc(1'b1, lfsr[4:0]);
        end
        repeat (100) begin
            rnd;
            cyc(1'b1, lfsr[4:0] & lfsr[12:8]);
        end

        // Reset during traffic with the pointer moved away from 0.
        cyc(1'b1, 5'b00001);
        repeat (2) cyc(1'b0, 5'b11110);
        repeat (10) cyc(1'b1, 5'b11111);

        // Random traffic with occasional resets.
        repeat (60) begin
            rnd;
            cyc((lfsr[23:20] != 4'h0), lfsr[4:0]);
        end

        repeat (3) cyc(1'b1, 5'b00000);
        @(negedge clk);

        check(ci4   != 32'd0, 1, 4);
        check(ca4   == 4'b1111, 2, 4);
        check(call4 != 32'd0, 3, 4);
        check(ch4   != 32'd0, 4, 4);
        check(cm4   != 32'd0, 5, 4);
        check(cr4   != 32'd0, 6, 4);
        check(ci5   != 32'd0, 1, 5);
        check(ca5   == 5'b11111, 2, 5);
        check(call5 != 32'd0, 3, 5);
        check(ch5   != 32'd0, 4, 5);
        check(cm5   != 32'd0, 5, 5);
        check(cr5   != 32'd0, 6, 5);

        passed = passed + p4 + p5;
        failed = failed + f4 + f5;

        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule

// One arbiter instance with its reference model, fairness and coverage.
module rr_arbiter_tb_lane #(
    parameter integer N = 4
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire [N-1:0] req,
    output reg  [31:0]  passed,
    output reg  [31:0]  failed,
    output reg  [31:0]  cov_idle,
    output reg  [N-1:0] cov_alone,
    output reg  [31:0]  cov_all,
    output reg  [31:0]  cov_held,
    output reg  [31:0]  cov_maxwait,
    output reg  [31:0]  cov_rst_traffic
);

    localparam [N-1:0] ZERO = {N{1'b0}};
    localparam [N-1:0] ALL  = {N{1'b1}};
    localparam [N-1:0] ONE  = {{(N-1){1'b0}}, 1'b1};

    wire [N-1:0] grant;

    rr_arbiter #(.N(N)) dut (
        .clk(clk), .rst_n(rst_n), .req(req), .grant(grant)
    );

    reg          started = 1'b0;
    integer      m_ptr;
    integer      winner;
    integer      k;
    integer      idx;
    integer      wait_cnt [0:N-1];
    reg  [N-1:0] exp_grant;
    reg  [N-1:0] prev_req;
    reg  [N-1:0] bit_k;
    reg          req_k;
    reg          grant_k;

    always @(posedge clk) begin
        if (!started) begin
            // First edge: initialise the model; the DUT is reset on this edge.
            started         = 1'b1;
            passed          = 32'd0;
            failed          = 32'd0;
            cov_idle        = 32'd0;
            cov_alone       = ZERO;
            cov_all         = 32'd0;
            cov_held        = 32'd0;
            cov_maxwait     = 32'd0;
            cov_rst_traffic = 32'd0;
            m_ptr           = 0;
            for (k = 0; k < N; k = k + 1) begin
                wait_cnt[k] = 0;
            end
            prev_req = req;
            if (rst_n) begin
                failed = failed + 32'd1;
                $error("N=%0d: the first clock edge must be in reset", N);
            end
        end else begin
            // Reference model: first requester at or after the pointer, modulo N.
            exp_grant = ZERO;
            winner    = -1;
            for (k = 0; k < N; k = k + 1) begin
                idx = (m_ptr + k) % N;
                if ((winner < 0) && ((req & (ONE << idx)) != ZERO)) begin
                    winner    = idx;
                    exp_grant = ONE << idx;
                end
            end

            if (grant === exp_grant) begin
                passed = passed + 32'd1;
            end else begin
                failed = failed + 32'd1;
                $error("N=%0d t=%0t: rst_n=%b req=%b ptr=%0d grant=%b expected %b",
                       N, $time, rst_n, req, m_ptr, grant, exp_grant);
            end

            // Fairness bound and per-requester coverage.
            for (k = 0; k < N; k = k + 1) begin
                bit_k   = ONE << k;
                req_k   = ((req & bit_k) != ZERO);
                grant_k = ((grant & bit_k) != ZERO);
                if (!rst_n) begin
                    wait_cnt[k] = 0;
                end else if (req_k && !grant_k) begin
                    wait_cnt[k] = wait_cnt[k] + 1;
                    if (wait_cnt[k] > N - 1) begin
                        failed = failed + 32'd1;
                        $error("N=%0d t=%0t: requester %0d has waited %0d cycles",
                               N, $time, k, wait_cnt[k]);
                    end else begin
                        passed = passed + 32'd1;
                    end
                end else begin
                    if (grant_k && (wait_cnt[k] == N - 1)) begin
                        cov_maxwait = cov_maxwait + 32'd1;
                    end
                    wait_cnt[k] = 0;
                end

                if (rst_n && (req == bit_k) && grant_k) begin
                    cov_alone = cov_alone | bit_k;
                end
                if (rst_n && req_k && ((prev_req & bit_k) != ZERO) &&
                    (((req ^ prev_req) & ~bit_k) != ZERO)) begin
                    cov_held = cov_held + 32'd1;
                end
            end

            if (rst_n && (req == ZERO)) cov_idle = cov_idle + 32'd1;
            if (rst_n && (req == ALL))  cov_all  = cov_all + 32'd1;
            if (!rst_n && (req != ZERO) && (m_ptr != 0)) begin
                cov_rst_traffic = cov_rst_traffic + 32'd1;
            end

            // Model pointer update.
            if (!rst_n) begin
                m_ptr = 0;
            end else if (winner >= 0) begin
                m_ptr = (winner + 1) % N;
            end
            prev_req = req;
        end
    end

endmodule
